import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create material with texture nodes
  const textureNode = texture(null);
  const material = new MeshBasicNodeMaterial({
    colorNode: textureNode,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position
  if (config.scenePosition) {
    mesh.position.copy(config.scenePosition);
  }
  if (config.rotation) {
    mesh.rotation.setFromVector3(config.rotation);
  }
  if (config.scale) {
    mesh.scale.copy(config.scale);
  }

  // Load and apply texture asynchronously
  texturePromise.then((tex) => {
    // Update texture node with loaded texture
    textureNode.value = tex;
    material.needsUpdate = true;
  });

  // Setup userData with cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
}
